    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int k = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] cooldown = new long[k];
        for (int i = 0; i < k; i++) {
            in.nextToken();
            cooldown[i] = (long) in.nval;
        }
        long[] time = new long[m];
        int[] type = new int[m];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            time[i] = (long) in.nval;
            in.nextToken();
            type[i] = (int) in.nval;
        }
        boolean[] res = processEvents(cooldown, time, type);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) sb.append(res[i] ? "true" : "false").append('\n');
        System.out.print(sb);
    }
}
